import { React, useState, useRef } from "react";
import * as Tone from 'tone';
import { Midi } from '@tonejs/midi';
import * as Soundfont from 'soundfont-player';
import { generateAccompanimentTrack } from "../../utils/chordParser";

// Component to playback midiData and download MIDI file
export default function MidiPlayer({ midiData, beats, tempo = 120, fileName = "Jazz_Solo" }) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [playChords, setPlayChords] = useState(true);
  const [isLoading, setIsLoading] = useState(false);

  // Store MIDI context and instrument

  const soloInstrumentRef = useRef(null);
  const chordInstrumentRef = useRef(null);
  const audioContextRef = useRef(null);
  const scheduledNotesRef = useRef([]);

  // Load instruments for playback
  const loadInstruments = async () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
    }
    const ac = audioContextRef.current;

    if (!soloInstrumentRef.current) {
      soloInstrumentRef.current = await Soundfont.instrument(ac, 'alto_sax');
    }
    if (playChords && !chordInstrumentRef.current) {
      chordInstrumentRef.current = await Soundfont.instrument(ac, 'acoustic_grand_piano');
    }
  };

  const playMidi = async () => {
    setIsLoading(true);

    try {
      await loadInstruments();
      await getAudioCOntext().resume();

      const response = await fetch(midiData);
      const arrayBuffer = await response.arrayBuffer();
      const midi = new Midi(arrayBuffer);

      // Schedule solo notes
      midi.tracks.forEach(track => {
        track.notes.forEach(note => {
          const time = note.time;
          const duration = note.duration;
          const velocity = note.velocity;
          const scheduledNote = soloInstrumentRef.current.play(note.name, getAudioContext().currentTime + time, { duration, gain: velocity });
          scheduledNotesRef.current.push(scheduledNote);
        });
      });

      // Schedule chord accompaniment if enabled
      if (playChords && beats?.length) {
        const accompanimentTrack = generateAccompanimentTrack(beats, tempo);
        accompanimentTrack.notes.forEach(note => {
          const time = note.time;
          const duration = note.duration;
          const velocity = note.velocity;
          const scheduledNote = chordInstrumentRef.current.play(note.name, getAudioContext().currentTime + time, { duration, gain: velocity });
          scheduledNotesRef.current.push(scheduledNote);
        });
      }

      // auto-stop


      setIsPlaying(true);
    } catch (error) {
      console.error('Error playing MIDI:', error);
      setIsPlaying(false);
    }
    finally {
      setIsLoading(false);
    }
  };

  const stopMidi = () => {
    // Stop all scheduled notes
    scheduledNotesRef.current.forEach(node => {
      if (node && node.stop) node.stop();
    });
    scheduledNotesRef.current = [];

    // Stop the instrument
    if (soloInstrumentRef.current) {
      soloInstrumentRef.current.stop();
    }
    if (chordInstrumentRef.current) {
      chordInstrumentRef.current.stop();
    }

    setIsPlaying(false);
  };

  const handlePlayPause = () => {
    setIsPlaying(!isPlaying);
    isPlaying ? stopMidi() : playMidi();
  };

  return (
    <div className="w-full mb-8 mt-8 p-6 bg-transparent shadow-md rounded-xl border border-gray-800 text-white flex flex-col items-center">
      <h2 className="text-3xl p-2 font-semibold mb-4">MIDI PLAYER</h2>

      {/* Download MIDI Button */}
        <a
            href={midiData}
            download={`${fileName}.mid`}
            className="mb-4 px-4 py-2 bg-amber-500 text-gray-900 font-semibold rounded hover:bg-amber-600 transition"
        >
            Download MIDI File
        </a>

      {/* Play/Pause Button */}
      <button
        onClick={handlePlayPause}
        className={`
          px-6 py-2 rounded-xl font-semibold text-lg transition-all duration-200
          ${isPlaying 
            ? "bg-red-600 hover:bg-red-500 text-white" 
            : "bg-amber-500 hover:bg-amber-400 text-gray-900"
          }
        `}
      >
        {isPlaying ? "Pause Playback" : "Play MIDI"}
      </button>
    </div>
  );
}
